import{_ as e,c as r,o as t,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"隱私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy.md","filePath":"zh-TW/guide/privacy.md","lastUpdated":1791311600000}'),l={name:"zh-TW/guide/privacy.md"};function o(n,a,d,s,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="隱私政策" tabindex="-1">隱私政策 <a class="header-anchor" href="#隱私政策" aria-label="Permalink to &quot;隱私政策&quot;">​</a></h1><p>nPlyr 是一款面向 macOS 與 iOS 的原生影片播放器。你的隱私是我們的首要任務。</p><h2 id="本機優先設計" tabindex="-1">本機優先設計 <a class="header-anchor" href="#本機優先設計" aria-label="Permalink to &quot;本機優先設計&quot;">​</a></h2><ul><li>你的觀看歷程、書籤與下載內容<strong>完全儲存在你自己的裝置上</strong>。</li><li>應用程式<strong>不需要帳號，也不需要註冊</strong>。</li><li><strong>沒有遙測</strong>——nPlyr 不會將使用資料回傳。</li><li>一旦媒體已在你的裝置上，核心播放與下載功能可完全離線工作。</li></ul><h2 id="網路使用由使用者主導" tabindex="-1">網路使用由使用者主導 <a class="header-anchor" href="#網路使用由使用者主導" aria-label="Permalink to &quot;網路使用由使用者主導&quot;">​</a></h2><p>nPlyr 只在<em>你</em>要求時才使用網路：</p><ul><li>串流播放或下載你開啟或擷取的影片。</li><li>使用內建嗅探器瀏覽。</li><li>執行你匯入的小程式 / 規則來源。</li></ul><p>我們不營運接收你的媒體、歷程或小程序變數的伺服器。</p><h2 id="瀏覽器" tabindex="-1">瀏覽器 <a class="header-anchor" href="#瀏覽器" aria-label="Permalink to &quot;瀏覽器&quot;">​</a></h2><p>內建瀏覽器是一個標準的 <code>WKWebView</code>。它不會注入自身的追蹤器。Cookie 與本機儲存都留在應用程式的容器中，與其他任何瀏覽器一樣。</p><h2 id="小程式資料" tabindex="-1">小程式資料 <a class="header-anchor" href="#小程式資料" aria-label="Permalink to &quot;小程式資料&quot;">​</a></h2><p>小程式是社群提供的規則，執行在沙盒化的 JavaScript 引擎中。規則儲存的任何變數（<code>setItem</code> / <code>getItem</code>）都保存在你裝置上的應用程式本機儲存中。nPlyr 不會讀取或傳輸它們。</p><h2 id="偵錯日誌" tabindex="-1">偵錯日誌 <a class="header-anchor" href="#偵錯日誌" aria-label="Permalink to &quot;偵錯日誌&quot;">​</a></h2><p>如果你啟用了偵錯日誌，日誌會被寫入本機，並且只有在<em>你</em>選擇匯出它們以回報問題時才會被分享。</p><h2 id="你的選擇" tabindex="-1">你的選擇 <a class="header-anchor" href="#你的選擇" aria-label="Permalink to &quot;你的選擇&quot;">​</a></h2><ul><li>隨時刪除單一歷程 / 書籤 / 下載項目。</li><li>從<strong>設定 → 進階 → 重設</strong>重置所有本機資料。</li><li>從<strong>小程式</strong>管理器中移除一個小程式及其儲存的變數。</li></ul><p>nPlyr 的設計預設就是私密的——沒有什麼需要「退出」。</p>',17)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
